def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    suitcases = image_patch.find("black suitcase")
    sidewalks = image_patch.find("sidewalk")
    cars = image_patch.find("car")

    if not suitcases or not sidewalks or not cars:
        return image_patch

    near_suitcases = []
    for suitcase in suitcases:
        for sidewalk in sidewalks:
            if distance(suitcase, sidewalk) < 0:
                near_suitcases.append(suitcase)
                break

    near_cars = []
    for suitcase in suitcases:
        for car in cars:
            if distance(suitcase, car) < 0:
                near_cars.append(suitcase)
                break

    if not near_suitcases and not near_cars:
        return image_patch

    if near_suitcases and not near_cars:
        return min(near_suitcases, key=lambda s: distance(s, image_patch))

    if not near_suitcases and near_cars:
        return min(near_cars, key=lambda s: distance(s, image_patch))

    return min(near_suitcases + near_cars, key=lambda s: distance(s, image_patch))

